<?php
declare(strict_types=1);require_once __DIR__.'/config/erp.php';$pdo=srnu_db();$mes=$_GET['mes']??date('Y-m');if(!preg_match('/^\d{4}-\d{2}$/',$mes))$mes=date('Y-m');$ini=$mes.'-01';$fin=date('Y-m-t',strtotime($ini));
function one(PDO $p,string $sql,array $a=[]):float{$s=$p->prepare($sql);$s->execute($a);return (float)$s->fetchColumn();}
$ventas=one($pdo,"SELECT COALESCE(SUM(subtotal),0) FROM cotizaciones WHERE fecha BETWEEN ? AND ? AND estado<>'Cancelado'",[$ini,$fin]);$iva=one($pdo,"SELECT COALESCE(SUM(iva),0) FROM cotizaciones WHERE fecha BETWEEN ? AND ? AND estado<>'Cancelado'",[$ini,$fin]);$cobrado=one($pdo,'SELECT COALESCE(SUM(monto),0) FROM pagos WHERE fecha BETWEEN ? AND ?',[$ini,$fin]);$gastos=one($pdo,'SELECT COALESCE(SUM(monto),0) FROM gastos WHERE fecha BETWEEN ? AND ?',[$ini,$fin]);$costos=one($pdo,'SELECT COALESCE(SUM(monto),0) FROM costos_reales WHERE fecha BETWEEN ? AND ?',[$ini,$fin]);$estim=one($pdo,"SELECT COALESCE(SUM(ci.costo_interno*ci.cantidad),0) FROM cotizacion_items ci JOIN cotizaciones c ON c.id=ci.cotizacion_id WHERE c.fecha BETWEEN ? AND ? AND c.estado<>'Cancelado'",[$ini,$fin]);
$s=$pdo->prepare("SELECT ci.concepto,COUNT(*) veces,SUM(ci.total) venta,SUM(ci.costo_interno*ci.cantidad) costo FROM cotizacion_items ci JOIN cotizaciones c ON c.id=ci.cotizacion_id WHERE c.fecha BETWEEN ? AND ? AND c.estado<>'Cancelado' GROUP BY ci.concepto ORDER BY venta DESC LIMIT 15");$s->execute([$ini,$fin]);$services=$s->fetchAll();$s=$pdo->prepare("SELECT cliente,telefono,COUNT(*) trabajos,SUM(total) total FROM cotizaciones WHERE fecha BETWEEN ? AND ? AND estado<>'Cancelado' GROUP BY cliente,telefono ORDER BY trabajos DESC,total DESC LIMIT 15");$s->execute([$ini,$fin]);$clients=$s->fetchAll();$s=$pdo->prepare("SELECT ci.tipo_entrega,COUNT(*) n,SUM(ci.total) total FROM cotizacion_items ci JOIN cotizaciones c ON c.id=ci.cotizacion_id WHERE c.fecha BETWEEN ? AND ? GROUP BY ci.tipo_entrega");$s->execute([$ini,$fin]);$types=$s->fetchAll();$low=(int)$pdo->query('SELECT COUNT(*) FROM inventario WHERE activo=1 AND stock<=stock_minimo')->fetchColumn();$post=(int)$pdo->query("SELECT COUNT(*) FROM postventa_recordatorios WHERE estado='Pendiente' AND fecha_recordatorio<=DATE_ADD(CURDATE(),INTERVAL 30 DAY)")->fetchColumn();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reportes · SRNU</title><?=srnu_ui_head()?></head><body><?php srnu_appbar('reportes');?><main class="w"><div class="srnu-page-heading"><div><h1>Reportes mensuales</h1><p>Ventas, utilidad, clientes, servicios y operación.</p></div></div><form class="toolbar"><input type="month" name="mes" value="<?=eh($mes)?>"><button class="btn">Ver mes</button></form><div class="kpi-grid" style="margin-top:16px"><div class="kpi"><small>Venta antes de IVA</small><strong><?=emoney($ventas)?></strong></div><div class="kpi"><small>Cobrado</small><strong><?=emoney($cobrado)?></strong></div><div class="kpi"><small>Gastos + costos reales</small><strong><?=emoney($gastos+$costos)?></strong></div><div class="kpi"><small>Resultado simple sobre cobrado</small><strong><?=emoney($cobrado-$gastos-$costos)?></strong></div></div><div class="grid-2" style="margin-top:16px"><section class="panel" style="padding:18px"><h3>Servicios más vendidos</h3><table><tr><th>Servicio</th><th>Veces</th><th>Venta</th><th>Utilidad estimada</th></tr><?php foreach($services as $r):?><tr><td><?=eh($r['concepto'])?></td><td><?=$r['veces']?></td><td><?=emoney($r['venta'])?></td><td><?=emoney((float)$r['venta']-(float)$r['costo'])?></td></tr><?php endforeach;?></table></section><section class="panel" style="padding:18px"><h3>Clientes del mes</h3><table><tr><th>Cliente</th><th>Trabajos</th><th>Total</th></tr><?php foreach($clients as $r):?><tr><td><?=eh($r['cliente'])?><div class="muted"><?=eh($r['telefono'])?></div></td><td><?=$r['trabajos']?></td><td><?=emoney($r['total'])?></td></tr><?php endforeach;?></table></section></div><div class="grid-3" style="margin-top:16px"><section class="card"><h3>Disponibilidad vendida</h3><?php foreach($types as $r):?><p><b><?=srnu_tipo_entrega_label($r['tipo_entrega'])?></b>: <?=$r['n']?> concepto(s) · <?=emoney($r['total'])?></p><?php endforeach;?></section><section class="card"><h3>Alertas</h3><p>Stock bajo: <b><?=$low?></b></p><p>Postventa próximos 30 días: <b><?=$post?></b></p></section><section class="card"><h3>Referencia financiera</h3><p>IVA generado: <b><?=emoney($iva)?></b></p><p>Costo presupuestado de conceptos: <b><?=emoney($estim)?></b></p><p>Gasto operativo: <b><?=emoney($gastos)?></b></p></section></div></main></body></html>
